<script>(function(){function loadRange(from,to){load_form('<?= base_url('dashboard/diagnosis') ?>?from_date='+encodeURIComponent(from)+'&to_date='+encodeURIComponent(to),'Diagnosis Dashboard');}$('#diagnosis_apply_range').off('click.diagnosisDash').on('click.diagnosisDash',function(){loadRange($('#diagnosis_from_date').val(),$('#diagnosis_to_date').val());});$('.diagnosis-range').off('click.diagnosisDash').on('click.diagnosisDash',function(){var end=new Date(),start=new Date();start.setDate(end.getDate()-Number($(this).data('days')||0));function ymd(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}loadRange(ymd(start),ymd(end));});})();</script>